#!/usr/bin/env python3
"""Rebuilds every page, the blog posts, sitemap.xml, robots.txt and manifest.json.
All changeable values live in js/config.js. Run on a computer: python3 tools/build.py"""
import re, json, os
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R)
cfg = open('js/config.js').read()
g = lambda k: re.search(k + r':\s*"([^"]*)"', cfg).group(1)
D, VER, GH, APK, MINA, DEV = g('domain').rstrip('/'), g('version'), g('github'), g('apkUrl'), g('minAndroid'), g('developerSite')
NAV = [('index','Home'),('features','Features'),('tour','App Tour'),('download','Download'),('premium','Premium'),('blog','Blog'),('about','About')]
SW = {"@context":"https://schema.org","@type":"SoftwareApplication","name":"FocusLock","operatingSystem":"Android","applicationCategory":"ProductivityApplication","softwareVersion":VER,"offers":{"@type":"Offer","price":"0","priceCurrency":"USD"},"url":D+"/"}
BTN = lambda t='Download FocusLock', c='': f'<a class="btn {c}" data-apk href="{APK}">{t}</a>'

def head(t, d, path, ld, base='', typ='website'):
    u = f'{D}/{path}'; im = f'{D}/assets/images/ogimg.jpg'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{t}</title><meta name="description" content="{d}"><link rel="canonical" href="{u}"><meta name="theme-color" content="#070b12">
<meta property="og:type" content="{typ}"><meta property="og:site_name" content="FocusLock"><meta property="og:title" content="{t}"><meta property="og:description" content="{d}"><meta property="og:url" content="{u}"><meta property="og:image" content="{im}">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{t}"><meta name="twitter:description" content="{d}"><meta name="twitter:image" content="{im}">
<link rel="icon" href="{base}favicon/favicon.ico" sizes="any"><link rel="icon" type="image/png" href="{base}favicon/favicon-32.png"><link rel="apple-touch-icon" href="{base}favicon/apple-touch-icon.png"><link rel="manifest" href="{base}manifest.json">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700&family=Figtree:wght@400;600&display=swap">
<link rel="stylesheet" href="{base}css/style.css"><script type="application/ld+json">{json.dumps(ld)}</script></head>'''
def header(cur, base=''):
    li = ''.join(f'<li><a href="{base}{k}.html"{" aria-current=page" if k==cur else ""}>{n}</a></li>' for k,n in NAV)
    return f'''<body data-base="{base}"><header><div class="w nav"><a class="logo" href="{base}index.html"><img src="{base}assets/icons/icon-192.png" width="32" height="32" alt="">FocusLock</a>
<nav aria-label="Main"><ul id="menu">{li}</ul></nav><a class="btn sm" data-apk href="{APK}">Download</a><button id="mb" aria-expanded="false" aria-controls="menu" aria-label="Menu">☰</button></div></header><main>'''
def footer(base='', blog=False):
    L = lambda p,n: f'<a href="{base}{p}.html">{n}</a>'
    return f'''</main><footer><div class="w fg"><div><h3>FocusLock</h3><p>Set limits for distracting apps, lock them when time is up, and unlock only on purpose. Made for Android.</p></div>
<div><h3>Product</h3>{L('features','Features')}{L('tour','App Tour')}{L('download','Download')}{L('premium','Premium')}</div>
<div><h3>Resources</h3>{L('blog','Blog')}{L('faq','FAQ')}{L('about','About')}<a data-gh href="{GH}" target="_blank" rel="noopener">GitHub</a></div>
<div><h3>Legal</h3>{L('privacy','Privacy policy')}{L('terms','Terms')}<a data-mail href="{base}about.html#contact">Contact</a></div></div>
<div class="w copy">© <span data-cfg="year">2026</span> FocusLock by <a data-dev href="{DEV}" target="_blank" rel="noopener">Zihad</a>.</div></footer>
<script src="{base}js/config.js"></script><script src="{base}js/main.js"></script>{f'<script src="{base}js/blog.js" data-base="{base}"></script>' if blog else ''}</body></html>'''

# ---------- building blocks ----------
def phone(name, alt, base='', lazy=True):
    return f'<div class="phone"><img src="{base}assets/screenshots/{name}.webp" width="520" height="1040" alt="{alt}"{" loading=lazy" if lazy else ""} onerror="this.parentNode.hidden=true"></div>'
def shot(name, cap, alt):
    return f'<figure class="shot">{phone(name, alt)}<figcaption>{cap}</figcaption></figure>'
card = lambda h, p, i='': f'<div class="card">{f"<div class=ic>{i}</div>" if i else ""}<h3>{h}</h3><p>{p}</p></div>'
def head2(eyebrow, h, p=''): return f'<p class="eyebrow">{eyebrow}</p><h2>{h}</h2>' + (f'<p class="lead">{p}</p>' if p else '')
def det(q, a): return f'<details><summary>{q}</summary><p>{a}</p></details>'
def row(eyebrow, h, body, phones, rev=False):
    return f'<section><div class="w split{" rev" if rev else ""}"><div class="prose">{head2(eyebrow,h)}{body}</div><div class="duo">{phones}</div></div></section>'
CTA = f'<section><div class="w"><div class="cta"><h2>Take back your time</h2><p>Free for Android. No account needed.</p><div class="row c">{BTN()}<a class="btn g" href="tour.html">Take the app tour</a></div></div></div></section>'
def page(name, t, d, body, ld=None, blog=False):
    open(f'{name}.html','w').write(head(t,d,f'{name}.html' if name!='index' else '',ld or SW)+header(name)+body+footer('',blog))
def faq_ld(items): return {"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":re.sub('<[^>]+>','',a)}} for q,a in items]}

FAQ = [
 ("What is FocusLock?","FocusLock is a free Android app. You pick distracting apps, set a daily limit for each, and FocusLock puts a block screen over them when time is up."),
 ("Is FocusLock free?","Yes. The free version shows ads. Premium removes the ads and nothing else changes."),
 ("Do I need an account?","No. There is no sign-up. Your limits and usage data stay on your phone."),
 ("What permissions does it need, and why?","Usage access to measure app time, the Accessibility service to see which app is open, Display over other apps to show the block screen, and Notifications for warnings. Do Not Disturb access is optional and only used in Focus mode. See the <a href='privacy.html'>privacy page</a> for details."),
 ("Can I set different limits for different apps?","Yes. Every app has its own switch and its own daily limit. You can also use limit templates and schedules."),
 ("What happens when a limit is reached?","A block screen appears over the app. You can stay locked in, complete an unlock challenge, or use one of your limited emergency bypasses."),
 ("What are unlock challenges?","Short tasks that add a pause before you get more time: a mental math question, a 30-second patience countdown, typing a sentence exactly, or your own PIN. You choose what is turned on."),
 ("Does FocusLock block emergency calls?","No. Phone calls and emergency functions are not blocked, and there are daily emergency bypasses for urgent needs."),
 ("What does Premium do?","It removes all advertisements from FocusLock. Plans: Weekly $0.29, Monthly $0.49, Quarterly $1.50 and Yearly $5."),
 ("How does Premium payment work?","Choose a plan in the app, pay the exact USDT amount with Binance Pay, enter the transaction ID in the app, and Premium turns on after the payment is verified. See the <a href='premium.html'>Premium page</a>."),
 ("What happens when Premium ends?","Premium works for the plan length you paid for. After that the app is free again and ads come back."),
 ("Where is my data stored?","On your device. FocusLock does not upload your usage history to its own servers."),
 ("Does it work offline?","Yes. Limits, blocking and tracking work without internet. The internet is used for ads in the free version and for checking Premium payments."),
 ("Is there an iPhone version?","No. FocusLock is made for Android only."),
 ("How do I update FocusLock?","Download the newest APK from the <a href='download.html'>download page</a> and install it over the old one."),
]

