page('about','About FocusLock','FocusLock is a privacy-first Android app that helps you control distracting apps and build better digital habits. Learn why it exists and how it works.',f'''
<section><div class="w prose"><p class="eyebrow">About</p><h1>About FocusLock</h1><p class="lead">FocusLock is an Android app that puts a simple barrier between you and distracting apps.</p>
{head2('The problem','Apps are built to keep you scrolling')}<p>Feeds, short videos and games are designed to be hard to put down. Willpower alone often loses.</p>
{head2('Who it is for','Anyone who wants more control')}<p>Students, workers, creators and anyone who opens an app without meaning to.</p>
{head2('How it works','Limits, a block screen, a pause')}<p>You pick apps and set daily limits. FocusLock tracks usage, warns you, and covers the app with a block screen when time is up. To get more time you complete a challenge you chose.</p>{steps_html}
{head2('Mission','Make distraction harder, focus easier')}<p>Without taking control away from you.</p>
{head2('Philosophy','You set the rules')}<p>FocusLock helps you keep them when it matters.</p>
{head2('Privacy first','No account, data on your phone')}<p>There is no sign-up. Your limits and usage stay on your device. We do not need an account because nothing has to be synced. Read the <a href="privacy.html">privacy page</a>.</p>
{head2('Why Android','Where the tools are')}<p>FocusLock uses Android features such as usage access and the Accessibility service to see which app is open. That is why it is built for Android.</p>
{head2('Difference','What makes it different')}<ul><li>Unlocking takes a deliberate challenge you choose.</li><li>Usage data stays on your device.</li><li>Calls and emergencies are never blocked.</li><li>Six themes and six languages.</li></ul>
{head2('Developer','Made by Zihad')}<p>FocusLock is made by <a data-dev href="{DEV}">Zihad</a>. Source and releases: <a data-gh href="{GH}">GitHub</a>.</p>
{head2('Contact','Get in touch').replace('<h2>','<h2 id="contact">')}<p>Email: <a data-mail href="#"><span data-cfg="email"></span></a></p></div></section>{CTA}''')

page('faq','FocusLock FAQ: answers to common questions','Answers about FocusLock: is it free, permissions, limits, unlock challenges, Premium, payment, privacy and updates.',f'<section><div class="w prose"><p class="eyebrow">FAQ</p><h1>Frequently asked questions</h1>{"".join(det(q,a) for q,a in FAQ)}<p>Still stuck? See <a href="about.html#contact">Contact</a>.</p></div></section>{CTA}',faq_ld(FAQ))

page('privacy','Privacy Policy | FocusLock','How FocusLock handles your data: what stays on your device, permissions, ads, and Premium payment checks.',f'''
<section><div class="w"><p class="eyebrow">Privacy</p><h1>Your privacy</h1><p class="lead">The short version first, then the full policy. Items marked [CONFIG] depend on your setup and must be reviewed before launch.</p>
<div class="grid">{card('No account','There is no sign-up or login.','👤')}{card('Data on your device','Limits, usage and goals are stored locally.','📱')}{card('No usage upload','FocusLock does not upload your usage history to its own servers.','🔒')}{card('Calls stay open','Phone and emergency functions are never blocked.','📞')}</div></div></section>
<section><div class="w">{head2('Permissions','What FocusLock can access, and why')}{perm_table}</div></section>
<section><div class="w prose"><h2>Full policy</h2>
<h3>Information collected</h3><p>FocusLock stores your app limits, usage statistics, goals, streaks and settings in a local database on your device.</p>
<h3>Information not collected</h3><p>FocusLock does not read your messages, passwords or keystrokes, and does not upload your usage history to its own servers. Analytics collection is turned off in the app.</p>
<h3>App usage and accessibility data</h3><p>The Accessibility service is used to detect which app is in the foreground so the block screen can appear.</p>
<h3>Local storage and backups</h3><p>Data stays on your device. If you export a backup, the file is saved where you choose.</p>
<h3>Data deletion</h3><p>Uninstalling the app removes its local data from your device. [CONFIG: confirm backup-file handling]</p>
<h3>Advertising</h3><p>The free version shows ads from Adsterra in embedded web views. Adsterra may collect data under its own policy. Premium removes ads. [CONFIG: confirm ad partners]</p>
<h3>Premium and payment information</h3><p>Payments are made in Binance Pay. When you submit a transaction ID, the app checks it with Binance. FocusLock does not receive your Binance login. Premium expiry and used transaction IDs are stored on your device.</p>
<h3>Third-party services</h3><p>Adsterra (ads) and Binance (payment checks).</p>
<h3>Data security</h3><p>Data is kept on your device and protected by Android. No method is completely secure.</p>
<h3>Children's privacy</h3><p>FocusLock is not directed to children under 13. [CONFIG: review for your region]</p>
<h3>Changes</h3><p>We may update this policy and will change the date below.</p><p>Last updated: <span data-cfg="date"></span></p>
<h3>Contact</h3><p><a data-mail href="about.html#contact"><span data-cfg="email"></span></a></p></div></section>''')

page('terms','Terms of Service | FocusLock','Terms for using FocusLock, including Premium purchases, Binance payment verification and refunds.','''
<section><div class="w prose"><p class="eyebrow">Terms</p><h1>Terms of service</h1><p>Items marked [CONFIG] must be completed before launch.</p>
<h2>Acceptance of terms</h2><p>By using FocusLock you agree to these terms.</p><h2>Using FocusLock</h2><p>You may use FocusLock for personal digital wellbeing. You choose which apps and protections to enable.</p>
<h2>App functionality</h2><p>FocusLock limits and blocks apps you select. Optional protections can make it harder to disable the app during a session. Calls and emergency functions are not blocked.</p>
<h2>Premium purchases</h2><p>Premium removes ads for the plan length: 7, 30, 90 or 365 days. Prices are shown in the app and on the Premium page.</p>
<h2>Binance payment verification</h2><p>Pay the exact USDT amount through Binance Pay, then submit the transaction ID in the app. Premium activates after the payment is verified.</p>
<h2>Refund policy</h2><p>[CONFIG: add your refund policy here]</p>
<h2>Premium entitlement</h2><p>Premium is stored on your device and is active until the end of the plan period.</p>
<h2>Acceptable use</h2><p>Do not misuse FocusLock, tamper with payment checks, or reuse transaction IDs.</p>
<h2>Disclaimer</h2><p>FocusLock is provided as is, without warranties. It is a productivity tool and not medical advice.</p><h2>Changes to terms</h2><p>We may update these terms. Continued use means you accept them.</p>
<h2>Contact</h2><p><a data-mail href="about.html#contact"><span data-cfg="email"></span></a></p></div></section>''')

# ---------- blog posts: (slug, title, description, category, date, cover, html) ----------
P = lambda *x: ''.join(x)
POSTS = [
('reduce-screen-time','7 simple ways to reduce screen time','Practical steps to spend less time on distracting apps, and how app limits can help.','Habits','2026-09-20','bg-aurora',
 '<p>Most of us do not plan to lose an hour to a feed. It just happens. These steps make that harder.</p><h2>1. Pick the apps that cost you most</h2><p>Check your usage and choose the two or three apps that eat the most time. Start there.</p><h2>2. Set a daily limit per app</h2><p>A limit turns a vague wish into a number. In FocusLock you set a daily limit for each app you choose.</p><h2>3. Add friction</h2><p>When the limit is reached, make opening the app slower. See <a href="why-unlocking-should-take-effort.html">why unlocking should take effort</a>.</p><h2>4. Protect blocks of deep work</h2><p>Plan focus sessions. Read <a href="run-a-deep-focus-session.html">how to run a deep focus session</a>.</p><h2>5. Track it weekly</h2><p>Look at your trend once a week. Small drops add up.</p><h2>6. Keep emergencies easy</h2><p>Real needs should never be blocked. FocusLock never blocks calls and has daily emergency bypasses.</p><h2>7. Be kind to yourself</h2><p>Some days you will go over. Reset and try again tomorrow.</p>'),
('why-unlocking-should-take-effort','Why unlocking an app should take a little effort','A short pause between the urge and the app is often enough to change your mind.','Focus','2026-09-22','bg-cyber',
 '<p>Impulse opens are fast. A small barrier slows them down enough for you to ask: do I really want this?</p><h2>Make the pause useful</h2><p>FocusLock offers four unlock challenges: a math question, a 30-second patience countdown, typing a sentence exactly, or your own PIN. You choose which ones are on.</p><h2>Keep real emergencies easy</h2><p>FocusLock never blocks calls or emergency functions, and it has daily emergency bypasses for urgent needs.</p><p>Next: <a href="reduce-screen-time.html">7 ways to reduce screen time</a>.</p>'),
('run-a-deep-focus-session','How to run a deep focus session','A simple routine for 15 minutes to 2 hours of work without distractions.','Productivity','2026-09-24','bg-ocean',
 '<p>Deep work needs a clear start, a clear end, and fewer interruptions in between.</p><h2>Before you start</h2><p>Pick one task and one duration. FocusLock Focus mode lets you choose from 15 minutes to 2 hours.</p><h2>During the session</h2><p>Distracting apps stay blocked until the timer ends. With your permission, FocusLock can also use Do Not Disturb to quiet notifications.</p><h2>After</h2><p>Take a real break away from the screen, then plan the next one. See also <a href="reduce-screen-time.html">reduce screen time</a>.</p>'),
('how-app-limits-work-on-android','How app limits work on Android','What happens behind the scenes when an app limit is reached, and why FocusLock asks for certain permissions.','Android','2026-09-26','bg-sakura',
 '<p>An app limit has three jobs: measure time, notice the app, and show a block screen.</p><h2>1. Measuring time</h2><p>Android shares app usage with apps that you allow. In FocusLock this is called Usage access.</p><h2>2. Noticing the app</h2><p>The Accessibility service tells FocusLock which app is in front. FocusLock uses it only for that.</p><h2>3. Showing the block screen</h2><p>With permission to display over other apps, FocusLock covers the limited app.</p><p>See every permission on the <a href="../privacy.html">privacy page</a>, or follow <a href="set-your-first-limit-in-focuslock.html">the first-limit guide</a>.</p>'),
('avoid-endless-scrolling','How to avoid endless scrolling','Feeds have no end on purpose. Here is how to add one yourself.','Habits','2026-09-28','bg-cyber',
 '<p>A feed never says "that is all". You have to say it.</p><h2>Decide the stop before you start</h2><p>Choose a time or a number of posts before you open the app.</p><h2>Use a limit as your stop</h2><p>A daily limit ends the session for you. See <a href="choosing-the-right-daily-limit.html">choosing the right daily limit</a>.</p><h2>Move the app out of reach</h2><p>Put it in a folder or off the home screen.</p><h2>Notice the habit</h2><p>If you open an app without deciding to, that is the habit to work on. A short challenge before unlocking helps you notice it.</p>'),
('build-a-focused-android-setup','How to build a focused Android setup','A few settings that make your phone calmer.','Android','2026-09-30','bg-aurora',
 '<h2>Clean the home screen</h2><p>Keep only the apps you use on purpose.</p><h2>Turn off notifications you do not need</h2><p>Keep calls and messages from people. Silence the rest.</p><h2>Add limits to the usual suspects</h2><p>Use <a href="set-your-first-limit-in-focuslock.html">FocusLock limits</a> for video, social and games.</p><h2>Use Focus mode for work</h2><p>See <a href="run-a-deep-focus-session.html">how to run a deep focus session</a>.</p>'),
('set-your-first-limit-in-focuslock','How to set your first limit in FocusLock','A step-by-step guide to installing FocusLock and setting your first app limit.','Tutorials','2026-10-01','bg-ocean',
 '<ol><li>Download FocusLock from the <a href="../download.html">download page</a> and install it.</li><li>Grant the permissions the app asks for: Usage access, Accessibility and Display over other apps.</li><li>Open the Apps tab and find an app you want to control.</li><li>Switch it on and set a daily limit.</li><li>Open Settings and choose the unlock challenges you want.</li></ol><p>That is it. When the limit is reached, a block screen appears. See the <a href="../tour.html">app tour</a> for every screen.</p>'),
('choosing-the-right-daily-limit','Choosing the right daily limit','Too strict and you give up. Too loose and nothing changes.','Productivity','2026-10-02','bg-sakura',
 '<h2>Start from your real number</h2><p>Look at how long you use the app today. Your first limit is a little less than that.</p><h2>Lower it in small steps</h2><p>Reduce the limit each week, not all at once.</p><h2>Use different limits for different apps</h2><p>An app you need for work gets a different limit than a game.</p><h2>Review the trend</h2><p>The Stats screen shows your daily trend. Adjust if you keep hitting the limit early.</p><p>Related: <a href="avoid-endless-scrolling.html">avoid endless scrolling</a>.</p>'),
('using-streaks-to-stay-consistent','Using streaks to stay consistent','A streak is a simple way to keep a habit going.','Habits','2026-10-03','bg-cyber',
 '<p>FocusLock tracks a focus streak: finish a focus session each day to grow it.</p><h2>Start small</h2><p>One 15-minute session counts as a start.</p><h2>Aim for the first milestones</h2><p>The app shows milestones at 3, 7, 14 and 30 days.</p><h2>If you miss a day</h2><p>Begin again. Consistency over time matters more than a perfect record.</p><p>Plan your sessions with <a href="run-a-deep-focus-session.html">this routine</a>.</p>'),
('phone-free-mornings-and-evenings','Phone-free mornings and evenings','Small boundaries around the start and end of your day.','Digital Wellbeing','2026-10-04','bg-aurora',
 '<p>This is general advice about habits, not medical advice.</p><h2>Mornings</h2><p>Wait before opening social apps. Start with something offline.</p><h2>Evenings</h2><p>Pick a time to put distracting apps away. Use a schedule or <a href="run-a-deep-focus-session.html">Focus mode</a> if it helps.</p><h2>Keep it realistic</h2><p>One boundary you keep beats five you do not. Also read <a href="reduce-screen-time.html">7 ways to reduce screen time</a>.</p>'),
]
def post_page(p):
    s,t,d,c,dt,im,body = p; path=f'posts/{s}.html'
    ld={"@context":"https://schema.org","@type":"Article","headline":t,"description":d,"datePublished":dt,"image":f"{D}/assets/images/{im}.webp","author":{"@type":"Person","name":"Zihad"},"publisher":{"@type":"Organization","name":"FocusLock"},"mainEntityOfPage":f"{D}/{path}"}
    cta = CTA.replace('href="tour.html"','href="../tour.html"')
    return head(f'{t} | FocusLock Blog',d,path,ld,'../','article')+header('blog','../')+f'<article><section><div class="w prose"><p class="meta">{c} · {dt}</p><h1 style="font-size:clamp(2rem,5vw,3rem)">{t}</h1><img src="../assets/images/{im}.webp" alt="" width="540" height="300" style="width:100%;height:260px;object-fit:cover;border-radius:18px;margin:20px 0">{body}<p><a href="../blog.html">← All articles</a></p></div></section></article><section><div class="w"><h2>Related articles</h2><div class="grid" id="related"></div></div></section>'+cta+footer('../',True)
os.makedirs('posts',exist_ok=True)
for f in os.listdir('posts'):
    if f.endswith('.html'): os.remove('posts/'+f)
for p in POSTS: open(f'posts/{p[0]}.html','w').write(post_page(p))
json.dump([{"title":p[1],"slug":p[0],"description":p[2],"category":p[3],"date":p[4],"image":f"assets/images/{p[5]}.webp","url":f"posts/{p[0]}.html"} for p in POSTS],open('data/posts.json','w'),indent=2)
urls=[''if k=='index' else k+'.html' for k,_ in NAV]+['faq.html','privacy.html','terms.html']+['posts/'+p[0]+'.html' for p in POSTS]
open('sitemap.xml','w').write('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{D}/{u}</loc></url>' for u in urls)+'</urlset>')
open('robots.txt','w').write(f'User-agent: *\nAllow: /\nSitemap: {D}/sitemap.xml\n')
json.dump({"name":"FocusLock","short_name":"FocusLock","start_url":"/","display":"standalone","background_color":"#070b12","theme_color":"#070b12","icons":[{"src":"assets/icons/icon-192.png","sizes":"192x192","type":"image/png"},{"src":"assets/icons/icon-512.png","sizes":"512x512","type":"image/png"}]},open('manifest.json','w'),indent=2)
print('built',len(urls),'urls')
